B.bsC=new A.C("Giri\u015f","Ayarlar > Hesap ve yedek > \u201cGoogle ile giri\u015f yap\u201d. Giri\u015f iste\u011fe ba\u011fl\u0131d\u0131r; giri\u015f yapmadan da uygulamay\u0131 tam kullanabilirsin.")
B.bsN=new A.C("Yedek","Giri\u015f yap\u0131nca kay\u0131tlar\u0131n, notalar\u0131n ve d\xfczeltmelerin buluta kopyalan\u0131r. Her de\u011fi\u015fiklik birka\xe7 saniye i\xe7inde kendili\u011finden yedeklenir; \u201c\u015eimdi e\u015fitle\u201d ile hemen de yedekleyebilirsin.")
B.bt_=new A.C("B\xfct\xfcn cihazlar\u0131nda","Ayn\u0131 Google hesab\u0131yla telefonda, iPhone\u2019da ya da bilgisayarda giri\u015f yaparsan ayn\u0131 kay\u0131tlar\u0131 g\xf6r\xfcrs\xfcn. Bir cihazda sildi\u011fin kay\u0131t \xf6tekilerden de silinir.")
B.bu_=new A.C("Yeni telefon","Telefon de\u011fi\u015firse ya da uygulama silinirse: uygulamay\u0131 kur, ayn\u0131 hesapla giri\u015f yap, kay\u0131tlar\u0131n geri gelsin.")
B.btP=new A.C("\xc7\u0131k\u0131\u015f ve silme","\u201c\xc7\u0131k\u0131\u015f yap\u201d ile yedek durur, kay\u0131tlar yerinde kal\u0131r. \u201cHesab\u0131m\u0131 ve yede\u011fimi sil\u201d buluttaki kopyay\u0131 ve hesab\u0131 tamamen siler; cihazdaki kay\u0131tlar kal\u0131r.")
B.aUh=s([B.bsC,B.bsN,B.bt_,B.bu_,B.btP],t.Wy)
B.a6p=new A.eQ(B.a7l,"Hesap ve yedek","Kay\u0131tlar\u0131n kaybolmas\u0131n, her cihaz\u0131nda olsun.",B.aUh)
B.AO=new A.aX(983396,"MaterialIcons",!1)
B.btG=new A.C("Varsay\u0131lanlar","Nota adlar\u0131n\u0131n ve b\xfcy\xfck notan\u0131n her kay\u0131tta a\xe7\u0131k gelip gelmeyece\u011fini se\xe7ebilirsin.")
B.btu=new A.C("G\xfcncelleme","Android uygulamas\u0131 yeni s\xfcr\xfcm\xfc kendisi bulur ve sorar; \u201cG\xfcncellemeleri denetle\u201d ile elle de bakabilirsin. Google Play\u2019den kurduysan g\xfcncellemeyi Play yapar. Web s\xfcr\xfcm\xfc her a\xe7\u0131l\u0131\u015fta en yenisidir.")
B.aYH=s([B.btG,B.btu],t.Wy)
B.a6v=new A.eQ(B.AO,"Ayarlar ve g\xfcncelleme","",B.aYH)
B.a7y=new A.aX(63625,"MaterialIcons",!1)
B.bu8=new A.C("Her \u015fey cihazda","Notaya \xe7evirme ve akor bulma telefonunda (web\u2019de taray\u0131c\u0131nda) yap\u0131l\u0131r; kay\u0131tlar\u0131n orada saklan\u0131r. Kay\u0131t i\xe7in internet gerekmez.")
B.bsM=new A.C("Yedek a\xe7\u0131ksa","Google ile giri\u015f yapt\u0131ysan kay\u0131tlar\u0131n ayr\u0131ca buluta (Google Firebase) yedeklenir. Yede\u011fini sadece sen g\xf6rebilirsin; ba\u015fka kimse eri\u015femez. \u0130stedi\u011fin an silebilirsin.")
B.btZ=new A.C("\u0130nternet ne zaman kullan\u0131l\u0131r","G\xfcncelleme kontrol\xfcnde, yedek a\xe7\u0131ksa e\u015fitlemede, \u201cSoru sor\u201d ve \u201cGeli\u015ftiriciye g\xf6nder\u201dde.")
B.bsk=new A.C("Telefon ve web","Android uygulamas\u0131 ve web s\xfcr\xfcm\xfc (iPhone dahil) ayn\u0131 i\u015fleri yapar. Giri\u015f yapmad\u0131ysan kay\u0131tlar her cihazda ayr\u0131 durur; giri\u015f yaparsan hepsinde ayn\u0131 kay\u0131tlar\u0131 g\xf6r\xfcrs\xfcn.")
B.aI2=s([B.bu8,B.bsM,B.btZ,B.bsk],t.Wy)
B.a6x=new A.eQ(B.a7y,"Gizlilik ve \xe7al\u0131\u015fma \u015fekli","Kay\u0131tlar\u0131n sende kal\u0131r.",B.aI2)
B.bsJ=new A.C("Baz\u0131 notalar yanl\u0131\u015f \xe7\u0131kt\u0131","D\xfczenle ile d\xfczeltebilirsin. S\u0131k oluyorsa kayd\u0131 daha sessiz bir yerde, notalar\u0131 daha net vurarak tekrar dene ya da \u201cGeli\u015ftiriciye g\xf6nder\u201d ile geli\u015ftiriciye yolla.")
B.bsb=new A.C("Mikrofon \xe7al\u0131\u015fm\u0131yor","Uygulamaya mikrofon izni ver (telefon ayarlar\u0131 > Uygulamalar > NotaGetir > \u0130zinler). Web\u2019de taray\u0131c\u0131n\u0131n mikrofon iznini a\xe7.")
B.bsG=new A.C("Akorlu (YZ) uzun s\xfcr\xfcyor","\u0130lk seferde normaldir; sonu\xe7 saklan\u0131r. Uzun kay\u0131tlarda bir iki dakika s\xfcrebilir.")
B.buh=new A.C("Sorum burada yok","Rehber\u2019in en alt\u0131ndaki \u201cSoru sor\u201d d\xfc\u011fmesiyle sorunu ya da \xf6nerini uygulama sahibine g\xf6nderebilirsin. Cevap istersen e-posta ya da telefonunu ekle.")
B.bt3=new A.C("Ses neden bir oktav farkl\u0131 yaz\u0131l\u0131","Saz notas\u0131 bir oktav yukar\u0131 yaz\u0131l\u0131r (yukar\u0131da \u201cNota sayfas\u0131\u201d b\xf6l\xfcm\xfcne bak). Bu bir hata de\u011fildir.")
